const BASE='/api/workspace/quant-strategies';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=value=>Array.isArray(value)?value:[];
const clone=structuredClone;
const when=value=>value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})+' KST':'—';
const state=value=>value==='APPROVED'?'발행됨':'초안';
const button=(title,action,id='',attributes='',appearance='')=>'<button type="button" class="button small'+(appearance?' '+appearance:'')+'" data-quant-action="'+action+'" data-quant-id="'+esc(id)+'" '+attributes+'>'+esc(title)+'</button>';
const menuItem=(label,action,id='',group='')=>({label,attributes:{'data-quant-action':action,'data-quant-id':id},group});
export function quantStrategyActions(entry,{includePrimary=true}={}){
 const draft=entry.status==='DRAFT',items=[menuItem(draft?'초안 편집':'새 버전 만들기','revise',entry.id,'전략 관리')];
 if(includePrimary)items.push(menuItem(draft?'검토·발행':'마인드에 추가',draft?'publish':'attach',entry.id,'전략 관리'));
 return [...items,menuItem('JSON 내보내기','export-json',entry.id,'내보내기'),menuItem('YAML 내보내기','export-yaml',entry.id,'내보내기')];
}
const row=(name,value)=>'<div class="detail-row"><span>'+esc(name)+'</span><strong>'+value+'</strong></div>';
const raw=value=>'<details class="spaced"><summary>전략 원문</summary><pre class="code">'+esc(JSON.stringify(value,null,2))+'</pre></details>';
const table=(head,rows,empty)=>rows.length?'<div class="studio-table-scroll"><table class="studio-table"><thead><tr>'+head.map(v=>'<th scope="col">'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(c=>'<tr>'+c.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<p class="empty">'+esc(empty)+'</p>';
const displayInstrument=id=>{try{const i=getInstrument(id);return i.symbol+' · '+i.venue.toUpperCase();}catch{return '종목 확인 필요';}};
const percent=value=>Number.isFinite(value)?(value*100).toFixed(2)+'%':'—';
const kindLabels={INPUT:'입력',SIGNAL:'가격 신호',CONDITION:'조건',QUANT:'퀀트 판단'};
const fieldLabels={lookbackBars:'관측 기간 · 봉',window:'이동평균 기간 · 봉',entryDeviation:'진입 이탈률',exitDeviation:'종료 이탈률',buyThreshold:'매수 기준',sellThreshold:'매도 기준',maWindow:'이동평균 기간 · 봉',dailyMaWindow:'일봉 이동평균 · 일',k:'민감도',h0:'기본 보유 편향',h1:'보유 편향 강도',shortWindow:'단기 관측 · 봉',longWindow:'장기 관측 · 봉',breakoutWindow:'돌파 관측 · 봉',minOpportunity:'최소 기회 점수',baseWeightRatio:'기본 목표 비중 배수',addProfitThreshold:'증액에 필요한 이익률',trailingStopRatio:'추적 청산 하락률',trendThreshold:'추세 기준',buyAbove:'매수 점수 기준',sellBelow:'매도 점수 기준',buyTargetWeight:'매수 전략 목표',sellTargetWeight:'매도 전략 목표',threshold:'조건 기준',value:'조건 기준',operator:'비교 연산',onTrue:'참일 때',onFalse:'거짓일 때',instrumentId:'입력 종목',metricId:'투자 지표',required:'필수 입력',maxAgeMs:'최대 자료 나이 · 밀리초'};
export function labelQuantStrategyInstance(graph,resource,instanceId){const next=clone(graph),binding=next.libraryBindings.find(b=>b.instanceId===instanceId),number=next.libraryBindings.filter(b=>b.resourceId===resource.id).length;if(binding)next.nodes.find(n=>n.id===binding.outputNodeId).label=resource.name+' · '+number;return next;}
export const isQuantLibrary=route=>route.page==='library'&&route.params.get('view')==='quant';
export function quantSourceChoices(minds=[]){return minds.flatMap(m=>{const manifest=m.manifest;if(!manifest?.data?.strategyPlan)return [];let graph;try{graph=strategyPlanGraph(manifest.data.strategyPlan);}catch{return [];}if(graph.schemaVersion!==2)return [];return graph.nodes.filter(n=>n.type==='QUANT').flatMap(n=>{try{const document=extractQuantStrategyResource(graph,{outputNodeId:n.id,id:'preview-'+m.id+'-'+n.id,version:1,name:n.label||manifest.data.name,description:'',createdAt:new Date().toISOString()});return [{id:m.id+'|'+n.id,name:manifest.data.name+' · '+n.label+' · 정책 v'+manifest.data.version,document}];}catch{return [];}});});}
const fieldChoices={operator:[['gt','초과 >'],['gte','이상 ≥'],['lt','미만 <'],['lte','이하 ≤']],onTrue:[['buy','매수'],['hold','유지'],['sell','매도']],onFalse:[['buy','매수'],['hold','유지'],['sell','매도']]};
export function quantEditableFields(definition){return list(definition?.nodes).flatMap((node,index)=>{
 const values=node.type==='SIGNAL'?node.config.parameters:node.config;
 return Object.entries(values).filter(([key,value])=>typeof value==='number'||typeof value==='boolean'||['operator','onTrue','onFalse','instrumentId','metricId'].includes(key)).map(([key,value])=>{
  const options=fieldChoices[key]||(key==='instrumentId'?listInstruments().filter(i=>node.config.kind!=='METRIC'||i.assetClass==='equity').map(i=>[i.id,i.symbol+' · '+i.venue.toUpperCase()]):key==='metricId'?QUANT_INPUT_METRICS.map(m=>[m.id,m.id+' · '+m.label]):null);
  if(options&&!options.some(([id])=>id===value))options.unshift([value,key==='instrumentId'?displayInstrument(value):value]);
  return {name:'node.'+index+'.'+key,nodeId:node.id,title:fieldLabels[key]||key,nodeName:node.label||kindLabels[node.type],type:options?'select':typeof value==='boolean'?'boolean':'number',value,options,parameter:node.type==='SIGNAL'};
 });
});}

export function readQuantDefinition(values,definition){
 if(values.get('editSource')==='true'){let next;try{next=JSON.parse(values.get('definition'));}catch{throw new Error('전략 원문의 JSON 형식을 확인하세요.');}return assertQuantStrategyDefinition(next);}
 const next=clone(definition);
 for(const field of quantEditableFields(definition)){const rawValue=values.get(field.name);if(rawValue===null)throw new Error(field.title+'을 입력하세요.');const value=field.type==='boolean'?rawValue==='true':field.type==='select'?rawValue:Number(rawValue);if(field.type==='number'&&(String(rawValue).trim()===''||!Number.isFinite(value)))throw new Error(field.title+'에 유효한 숫자를 입력하세요.');if(field.type==='select'&&!field.options.some(([id])=>id===value))throw new Error(field.title+'의 등록된 값을 선택하세요.');const node=next.nodes.find(n=>n.id===field.nodeId);if(field.parameter)node.config.parameters[field.name.split('.').at(-1)]=value;else node.config[field.name.split('.').at(-1)]=value;}
 for(const node of next.nodes.filter(n=>n.type==='SIGNAL'))node.config=createStrategyModule(node.config.moduleId,{parameters:node.config.parameters,required:node.config.required,parametersVersionId:node.id+'-'+crypto.randomUUID()});
 return assertQuantStrategyDefinition(next);
}
export function quantDefinitionMarkup(document){const d=document.definition,fields=quantEditableFields(d);return '<section class="quant-contract"><h3>입력 → 판단</h3>'+table(['단계','이름','설정'],list(d.nodes).map(n=>{
 const title=n.type==='INPUT'?[({OHLCV:'확정 시세',METRIC:'투자 지표',POSITION:'포트폴리오'})[n.config.kind]||'입력 자료',displayInstrument(n.config.instrumentId),n.config.timeframe==='4h'?'4시간봉':n.config.timeframe].filter(Boolean).join(' · '):n.type==='SIGNAL'?({MEAN_REVERSION:'평균 회귀',BTC_DOC9:'BTC 기준 전략',OPPORTUNITY:'기회 집중',SMA_TREND:'이동평균 추세',MOMENTUM:'가격 모멘텀'})[n.config.moduleId]||n.label:n.type==='QUANT'?'매수 · 유지 · 매도':'조건 비교';
 const settings=fields.filter(f=>f.nodeId===n.id&&!['instrumentId'].includes(f.name.split('.').at(-1))).map(f=>f.type==='boolean'?(f.value?'필수 입력':'선택 입력'):f.title+' '+(f.type==='select'?f.options.find(([id])=>id===f.value)?.[1]||f.value:f.value));
 return [esc(kindLabels[n.type]||n.type),esc(n.label),esc(title)+'<small class="studio-cell-secondary">'+esc(settings.join(' · '))+'</small>'];
}),'입력 경로를 확인하세요.')+row('출력',esc(d.nodes.find(n=>n.id===d.outputNodeId)?.label||d.outputNodeId)+' · 전략 목표 보유비중')+'</section>';}


export function createQuantStrategyLibrary(hooks){
 const modelLibrary=createStrategyModelLibrary(hooks);
 const committedForms=new WeakSet();
 let catalog=null,error='',loading=false,key='',generation=0,abort=null,started=false,pending=false,chooserGeneration=0,editor=null,lastDetail=null;
 const route=()=>hooks.getRoute(),current=token=>token===undefined||token===hooks.getDialogToken?.(),token=()=>hooks.getDialogToken?.();
 async function load({force=false}={}){if(!isQuantLibrary(route()))return;const query=new URLSearchParams();for(const k of ['search','status'])if(route().params.get(k))query.set(k,route().params.get(k));const next=query.toString();if(!force&&key===next&&catalog&&(!hooks.getRevision||catalog.revision===hooks.getRevision()))return;abort?.abort();abort=new AbortController();const seq=++generation;key=next;loading=true;error='';hooks.render?.();try{const [result]=await Promise.all([hooks.request(BASE+'?'+query,undefined,{signal:abort.signal}),modelLibrary.load()]);if(seq!==generation)return;catalog=result;}catch(e){if(seq===generation&&e.name!=='AbortError')error=e.message;}finally{if(seq===generation){loading=false;hooks.render?.();}}}
 function invalidate(){generation++;abort?.abort();catalog=null;key='';loading=false;error='';}
 function render(){
  const items=list(catalog?.items),query=route().params.get('search')||'',status=route().params.get('status')||'',filtered=!!query||!!status;
  const toolbar=renderActionMenu({id:'quant-library-actions',label:'라이브러리 작업',items:[menuItem('새 전략으로 가져오기','import'),menuItem('목록 새로고침','refresh')]});
  const filters='<form data-quant-form="search" class="studio-query-bar quant-query-bar"><label class="studio-record-search">검색<input type="search" name="search" aria-label="퀀트 전략 검색" value="'+esc(query)+'" placeholder="전략 이름·설명"></label><label>상태<select name="status" aria-label="퀀트 전략 상태"><option value="">전체</option>'+['DRAFT','APPROVED'].map(s=>'<option value="'+s+'"'+(status===s?' selected':'')+'>'+state(s)+'</option>').join('')+'</select></label><button class="button small" type="submit">검색</button>'+(filtered&&items.length?button('필터 지우기','clear-filters'):'')+'</form>';
  let body;
  if(loading)body='<div class="quant-empty" role="status"><p>전략을 불러오는 중…</p></div>';
  else if(error)body='<div class="quant-empty"><p role="alert">'+esc(error)+'</p>'+button('다시 불러오기','refresh')+'</div>';
  else if(!items.length)body='<div class="quant-empty"><h2>'+esc(filtered?'검색 결과가 없습니다':'첫 퀀트 전략을 만드세요')+'</h2><p>'+esc(filtered?[query?'“'+query+'”':'',status?state(status):''].filter(Boolean).join(' · '):'템플릿이나 마인드의 퀀트 판단에서 시작하세요.')+'</p>'+button(filtered?'필터 지우기':'새 전략',filtered?'clear-filters':'new','','','primary')+'</div>';
  else body=table(['전략','버전','상태','사용 중인 마인드','발행 시각','작업'],items.map(item=>[
   '<button type="button" class="studio-row-link quant-title" title="'+esc(item.name)+'" data-quant-action="detail" data-quant-id="'+esc(item.id)+'">'+esc(item.name)+'</button>',
   esc('v'+item.version),'<span class="quant-status" data-status="'+esc(item.status)+'">'+esc(state(item.status))+'</span>',Number.isSafeInteger(item.usageCount)?esc(item.usageCount):'—',esc(when(item.publishedAt)),
   renderActionMenu({id:'quant-row-'+item.id,label:item.name+' v'+item.version+' 작업',compact:true,items:quantStrategyActions(item)})
  ]),'');
  return modelLibrary.render()+(modelLibrary.isComponents()?'<div class="quant-library"><div class="studio-page-head"><div><h2>퀀트 부품</h2>'+helpLabel('공용 전략','입력부터 매수·유지·매도까지 완성된 전략을 발행합니다. 마인드마다 설정을 조정하고 새 버전을 따로 채택할 수 있습니다.')+'</div><div class="actions">'+toolbar+(catalog&&!loading&&!error&&!filtered&&!items.length?'':button('새 전략','new','','','primary'))+'</div></div>'+filters+'<section class="studio-sheet quant-catalog" aria-busy="'+loading+'">'+body+'</section></div>':'');
 }
 async function getCatalog(){return hooks.request(BASE);}
 async function item(id){return hooks.request(BASE+'/item?'+new URLSearchParams({id}));}
 async function detail(id){
  const at=token(),value=await item(id);if(!current(at))return;lastDetail=value;
  const entry=value.entry||value.item,doc=entry.document||value.document,usage=value.usage||{},versions=list(value.versions),minds=list(usage.minds),reports=list(usage.simulations||usage.benchmarks);
  const history=table(['버전','상태','발행 시각',''],versions.map(v=>['v'+v.version,esc(state(v.status)),esc(when(v.publishedAt)),v.id===entry.id?'<span class="quant-current-version">현재 버전</span>':button('버전 열기','detail',v.id)]),'저장 버전을 조회하세요.');
  const users=table(['마인드','정책','인스턴스',''],minds.map(m=>[esc(m.name||hooks.mindName?.(m.mindId||m.profileId)||m.mindId||m.profileId),esc('v'+(m.policyVersion??m.manifestVersion??'—')),esc(m.instanceId||list(m.instances).length||'—'),button('운용 열기','mind',m.mindId||m.profileId)]),'이 버전을 발행 정책에서 사용하는 마인드가 없습니다.');
  const results=table(['실험·기간','실행 구성','수익률','최대 낙폭','거래','비용',''],reports.map(s=>[
   esc(s.name||s.id)+'<small class="studio-cell-secondary">'+esc(when(s.startAt))+' ~ '+esc(when(s.endAt))+'</small>',
   esc(s.attribution==='STANDALONE_QUANT'?'단독 퀀트':'마인드 조합')+'<small class="studio-cell-secondary">'+esc(s.status==='COMPLETED'?(s.evaluation?.wholeWindowComparable?'전체 기간 평가':'평가 범위 확인'):({RUNNING:'실행 중',DRAFT:'준비',FAILED:'실행 확인 필요',PAUSED:'일시중지'})[s.status]||'보고서 확인')+'</small>',
   percent(s.metrics?.totalReturn),percent(s.metrics?.maxDrawdown),Number.isSafeInteger(s.metrics?.tradeCount)?esc(s.metrics.tradeCount):'—',Number.isFinite(s.metrics?.totalCosts)&&s.quoteCurrency?esc(s.metrics.totalCosts.toFixed(2)+' '+s.quoteCurrency):'—',button('보고서 열기','simulation',s.id,'data-quant-mind="'+esc(s.mindId||s.profileId)+'"')
  ]),'이 버전을 사용한 저장 보고서가 없습니다.');
  const actions=renderActionMenu({id:'quant-detail-actions-'+entry.id,label:'전략 작업',items:quantStrategyActions(entry,{includePrimary:false})})+button(entry.status==='DRAFT'?'검토·발행':'마인드에 추가',entry.status==='DRAFT'?'publish':'attach',entry.id,'','primary');
  const identity='<div class="quant-detail-identity"><strong>v'+esc(entry.version)+'</strong><span class="quant-status" data-status="'+esc(entry.status)+'">'+esc(state(entry.status))+'</span>'+(entry.review?.reviewedAt||entry.publishedAt?'<span class="quant-published-at">'+esc(when(entry.review?.reviewedAt||entry.publishedAt))+'</span>':'')+'</div>';
  hooks.open?.(doc.name,'<div class="quant-detail">'+identity+(doc.description?'<p class="quant-description">'+esc(doc.description)+'</p>':'')+quantDefinitionMarkup(doc)+
   '<details class="quant-detail-section"><summary><span>사용 · 검증</span><span class="quant-section-count">마인드 '+minds.length+' · 보고서 '+reports.length+'</span></summary><div class="quant-section-body"><h3>사용 중인 마인드</h3>'+users+'<h3>검증 보고서</h3>'+results+(usage.simulationPage?.hasMore?'<p class="tiny muted">최근 '+esc(usage.simulationPage.returned)+'개 보고서 표시 · 전체 '+esc(usage.simulationPage.total)+'개</p>':'')+'</div></details>'+
   '<details class="quant-detail-section"><summary><span>버전 기록</span><span class="quant-section-count">'+versions.length+'개</span></summary><div class="quant-section-body">'+history+'</div></details>'+raw(doc)+'</div>',actions);
 }
 function chooser(data){const templates=list(data.templates),sources=quantSourceChoices(hooks.getMinds?.());editor={templates,sources};hooks.open?.('퀀트 전략 만들기','<form data-quant-form="source" class="studio-form"><label class="field full">시작 전략<select name="source" required aria-label="시작 전략"><option value="">전략 선택</option><optgroup label="등록 템플릿">'+templates.map((s,i)=>'<option value="template:'+i+'">'+esc(s.name)+'</option>').join('')+'</optgroup><optgroup label="마인드의 퀀트 판단">'+sources.map((s,i)=>'<option value="mind:'+i+'">'+esc(s.name)+'</option>').join('')+'</optgroup></select></label><p class="full error-text" data-quant-error role="alert"></p><button class="button primary" type="submit">전략 설정</button></form>');}
 function syncEditMode(form){const mode=form?.querySelector?.('[name="editSource"]');if(!mode)return;const source=mode.checked,settings=form.querySelector('[data-quant-settings]'),raw=form.querySelector('[name="definition"]');settings.hidden=source;settings.disabled=source;raw.readOnly=!source;form.dataset.quantEditMode=source?'source':'settings';if(source)raw.closest('details').open=true;form.querySelector('[data-quant-edit-status]').textContent=source?'JSON 원문만 저장합니다. 설정 입력은 별도로 유지됩니다.':'노드 설정값을 저장합니다. JSON 원문은 확인용입니다.';}
 function change(event){const mode=event.target;if(mode.matches?.('[data-quant-source-mode]'))syncEditMode(mode.closest('[data-quant-form="edit"]'));}
 function edit(document,strategyId=null,draft=null){editor={document:clone(document),strategyId,draft};const groups=list(document.definition.nodes).map(n=>{const fields=quantEditableFields(document.definition).filter(f=>f.nodeId===n.id);return '<fieldset class="quant-node-fields"><legend>'+esc(n.label||kindLabels[n.type])+'</legend>'+fields.map(f=>'<label class="field">'+esc(f.title)+(f.type==='select'?'<select name="'+f.name+'">'+f.options.map(([id,title])=>'<option value="'+esc(id)+'"'+(f.value===id?' selected':'')+'>'+esc(title)+'</option>').join('')+'</select>':f.type==='boolean'?'<select name="'+f.name+'"><option value="true"'+(f.value?' selected':'')+'>필수</option><option value="false"'+(!f.value?' selected':'')+'>선택</option></select>':'<input name="'+f.name+'" type="number" step="any" required value="'+esc(f.value)+'">')+'</label>').join('')+'</fieldset>';}).join('');hooks.open?.(strategyId?'퀀트 전략 새 버전':'퀀트 전략 초안','<form data-quant-form="edit" data-draft-identity="'+esc(strategyId||document.id||document.name)+'" class="studio-form"><label class="field full">이름<input name="name" required maxlength="100" value="'+esc(document.name)+'"></label><label class="field full">설명<textarea name="description" maxlength="2000">'+esc(document.description||'')+'</textarea></label><div class="full quant-edit-mode"><label><input type="checkbox" name="editSource" value="true" data-quant-source-mode> JSON 원문으로 저장</label><p data-quant-edit-status role="status" aria-live="polite">노드 설정값을 저장합니다. JSON 원문은 확인용입니다.</p></div><fieldset class="full quant-edit-settings" data-quant-settings><legend>노드 설정</legend>'+groups+'</fieldset><details class="full quant-edit-source"><summary>전략 JSON 원문</summary><textarea class="code" name="definition" aria-label="퀀트 전략 원문" spellcheck="false" readonly>'+esc(JSON.stringify(document.definition,null,2))+'</textarea></details><p class="full error-text" data-quant-error role="alert" tabindex="-1"></p><button class="button primary" type="submit">전략 초안 저장</button></form>');if(typeof globalThis.document!=='undefined')syncEditMode(globalThis.document.querySelector?.('[data-quant-form="edit"]'));}
 function publish(id){hooks.open?.('퀀트 전략 발행','<form data-quant-form="publish" data-quant-id="'+esc(id)+'" class="studio-form"><div class="full">'+helpLabel('버전 발행','발행한 버전은 그대로 보존합니다. 기존 마인드에서 새 버전을 사용하려면 해당 마인드의 정책 초안에 채택하고 발행하세요.')+'</div><label class="field full">검토 내용<textarea name="reason" required maxlength="2000" placeholder="입력·계산 조건과 적용 범위를 확인한 내용을 기록하세요."></textarea></label><p class="full error-text" data-quant-error role="alert"></p><button class="button primary" type="submit">이 버전 발행</button></form>');}
 async function attachChooser(id){
  const generation=++chooserGeneration;hooks.open?.('전략을 사용할 마인드','<p class="empty" role="status">마인드 목록을 불러오는 중…</p>');const at=token();
  try{const minds=hooks.loadMinds?await hooks.loadMinds():hooks.getMinds?.();if(generation!==chooserGeneration||!current(at))return;
  hooks.open?.('전략을 사용할 마인드','<form data-quant-form="attach" data-quant-id="'+esc(id)+'" class="studio-form"><label class="field full">마인드<select name="mindId" data-quant-attach-mind required><option value="">마인드 선택</option>'+list(minds).filter(m=>m.manifest).map(m=>'<option value="'+esc(m.id)+'">'+esc(m.manifest.data.name+' · '+(m.manifest.data.strategyPlan?.graph?.schemaVersion===2?'현재 구성에 결합':'새 퀀트 구성'))+'</option>').join('')+'</select></label><div class="full">'+helpLabel('구성 적용','결정 그래프를 사용하는 마인드는 기존 결정과 새 전략을 50:50으로 결합합니다. 신호형 그래프를 사용하는 마인드는 선택한 퀀트 전략 한 개로 새 구성을 시작합니다. 현재 발행 정책은 새 정책을 발행할 때까지 유지됩니다.')+'</div><p class="full error-text" data-quant-error role="alert"></p><button class="button primary" type="submit">구성 초안에서 설정</button></form>');
  }catch(problem){if(generation===chooserGeneration&&current(at))hooks.open?.('전략을 사용할 마인드','<p class="empty" role="alert">'+esc(problem.message)+'</p>',button('마인드 다시 조회','attach',id));}
 }

 function importForm(){hooks.open?.('새 퀀트 전략으로 가져오기','<form data-quant-form="import" class="studio-form"><label class="field">형식<select name="format"><option value="json">JSON</option><option value="yaml">YAML</option></select></label><label class="field full">전략 원문<textarea name="source" required spellcheck="false" class="code"></textarea></label><p class="full error-text" data-quant-error role="alert"></p><button class="button primary" type="submit">가져오기</button></form>');}
 async function click(event){const b=event.target.closest?.('[data-quant-action]');if(!b||b.disabled||pending)return;const {quantAction:action,quantId:id}=b.dataset;event.preventDefault();try{if(action==='refresh')return load({force:true});if(action==='clear-filters')return hooks.navigate?.('library',{view:'quant',search:null,status:null});if(action==='detail')return await detail(id);if(action==='new'){const at=token(),data=await getCatalog();if(current(at))chooser(data);return;}if(action==='revise'){const at=token(),value=await item(id);if(current(at)){const entry=value.entry||value.item;edit(entry.document,entry.status==='APPROVED'?entry.strategyId:null,entry.status==='DRAFT'?{draftId:entry.id,expectedContentHash:entry.contentHash}:null);}return;}if(action==='publish')return publish(id);if(action==='attach')return attachChooser(id);if(action==='import')return importForm();if(action==='mind'){hooks.close?.();return hooks.navigate?.('minds',{profileId:id,view:'operations'});}if(action==='simulation'){hooks.close?.();return hooks.navigate?.('minds',{profileId:b.dataset.quantMind,view:'simulations',simulationId:id});}if(action.startsWith('export-')){const value=await hooks.request(BASE+'/export?'+new URLSearchParams({id,format:action.slice(7)}));return hooks.download?.(value.filename,value.text,value.contentType);}}catch(e){hooks.toast?.(e.message);}}
 async function submit(event){const form=event.target.closest?.('[data-quant-form]');if(!form)return;event.preventDefault();if(pending||hooks.isBusy?.()||committedForms.has(form))return;const values=new FormData(form),kind=form.dataset.quantForm,errorNode=form.querySelector('[data-quant-error]');if(errorNode)errorNode.textContent='';if(kind==='search')return hooks.navigate?.('library',{view:'quant',search:values.get('search')||null,status:values.get('status')||null});const submit=form.querySelector('[type="submit"]'),prior=submit?.textContent;pending=true;if(submit){submit.disabled=true;submit.textContent='처리 중…';}const at=token();let committed=false;try{if(kind==='source'){const [type,index]=String(values.get('source')).split(':'),source=type==='template'?editor?.templates[Number(index)]:editor?.sources[Number(index)]?.document;if(!source)throw new Error('시작 전략을 선택하세요.');edit(source);return;}if(kind==='attach'){const value=await item(form.dataset.quantId);if(!current(at))return;const entry=value.entry||value.item;if(entry.status!=='APPROVED')throw new Error('발행한 전략을 선택하세요.');await hooks.onAttach?.(values.get('mindId'),entry.document);return;}let payload,path;if(kind==='edit'){if(!editor?.document)throw new Error('전략 편집기를 다시 열어 주세요.');const definition=readQuantDefinition(values,editor.document.definition);payload={name:String(values.get('name')).trim(),description:String(values.get('description')).trim(),definition,...(editor.draft||{}),...(editor.strategyId?{strategyId:editor.strategyId}:{})};path=BASE+'/draft';}else if(kind==='publish'){payload={id:form.dataset.quantId,reason:String(values.get('reason')).trim()};if(!payload.reason)throw new Error('검토 내용을 입력하세요.');path=BASE+'/publish';}else if(kind==='import'){payload={text:values.get('source'),format:values.get('format')};path=BASE+'/draft';}else return;const result=await hooks.mutate('',payload,path,{onCommitted:()=>{committed=true;committedForms.add(form);clearFormDraft(form);}});committed=true;committedForms.add(form);clearFormDraft(form);catalog=null;key='';if(current(at)){const id=(result.entry||result.item)?.id;try{if(id)await detail(id);else hooks.close?.();}catch(e){hooks.close?.();hooks.toast?.('저장 완료 · 목록에서 저장한 버전을 다시 조회하세요.');}}await load({force:true});}catch(e){if(current(at)&&errorNode?.isConnected!==false){const message=committed?'저장 완료 · 목록에서 결과를 다시 조회하세요.':e.message;if(kind==='edit')revealDialogError(errorNode,message);else errorNode.textContent=message;}else hooks.toast?.(e.message);}finally{pending=false;if(submit?.isConnected!==false){submit.disabled=committed;submit.textContent=committed?'저장 완료':prior;}}}
 function start(){if(started)return;started=true;if(typeof document!=='undefined')modelLibrary.start();if(typeof document!=='undefined'){document.addEventListener('click',click);document.addEventListener('submit',submit);document.addEventListener('change',change);}}
 function destroy(){modelLibrary.destroy();generation++;chooserGeneration++;abort?.abort();if(started&&typeof document!=='undefined'){document.removeEventListener('click',click);document.removeEventListener('submit',submit);document.removeEventListener('change',change);}started=false;}
 return {load,invalidate,render,start,destroy,detail,click,submit,edit,state:()=>({catalog,error,loading,pending,lastDetail}),graphHooks:{models:async()=>hourlyModelSources(hooks.loadMinds?await hooks.loadMinds():hooks.getMinds?.()),list:()=>hooks.request(BASE+'?status=APPROVED'),read:item,register:async payload=>{const result=await hooks.mutate('',payload,BASE+'/draft');catalog=null;key='';return result.entry||result.item;}}};
}
